(function(){
  function reactFill(sel, val){
    const el = document.querySelector(sel);
    if(!el) return 'no-el';
    const setter = Object.getOwnPropertyDescriptor(
      el instanceof HTMLTextAreaElement ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype,
      'value').set;
    setter.call(el, val);
    el.dispatchEvent(new Event('input', {bubbles:true}));
    el.dispatchEvent(new Event('change', {bubbles:true}));
    return 'ok:' + el.value.slice(0,20);
  }
  const inputs = Array.from(document.querySelectorAll('input'));
  const nameI = inputs.find(i => i.placeholder === 'Add display name');
  const titleI = inputs.find(i => i.placeholder === 'Add title');
  let out = [];
  if (nameI) { nameI.setAttribute('data-bridge','name-input'); out.push('name found'); }
  if (titleI) { titleI.setAttribute('data-bridge','title-input'); out.push('title found'); }
  return out.join(',');
})()
